set-variable.value:
@{
    string[] values;
    if (!context.Request.Headers.TryGetValue("traceparent", out values) || values.Length == 0) return "absent";
    if (values.Length != 1) return "duplicate";
    var value = values[0];
    if (value == null || value.Length < 55 || value.Length > 256 || value.Contains(",")) return "invalid";
    if (value.Any(character => character < 0x21 || character > 0x7e)) return "invalid";
    var match = Regex.Match(value, "^([0-9a-f]{2})-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})");
    if (!match.Success || match.Groups[1].Value == "ff") return "invalid";
    if (match.Groups[2].Value == "00000000000000000000000000000000" || match.Groups[3].Value == "0000000000000000") return "invalid";
    if (match.Groups[1].Value == "00" && value.Length != 55) return "invalid";
    if (value.Length > 55 && value[55] != '-') return "invalid";
    return "valid";
  }

@{
    if ((string)context.Variables["contoso.traceparentDisposition"] != "valid") return false;
    string[] values;
    if (!context.Request.Headers.TryGetValue("tracestate", out values) || values.Length == 0) return true;
    var value = string.Join(",", values);
    if (value.Length > 512) return false;
    var members = value.Split(',');
    if (members.Length > 32) return false;
    var keys = new HashSet<string>(StringComparer.Ordinal);
    foreach (var rawMember in members) {
      var member = rawMember.Trim(' ', '\t');
      if (member.Length == 0) continue;
      var separator = member.IndexOf('=');
      if (separator <= 0 || separator != member.LastIndexOf('=')) return false;
      var key = member.Substring(0, separator);
      var entryValue = member.Substring(separator + 1);
      if (!Regex.IsMatch(key, "^(?:[a-z][a-z0-9_*/-]{0,255}|[a-z0-9][a-z0-9_*/-]{0,240}@[a-z][a-z0-9_*/-]{0,13})$") || !keys.Add(key)) return false;
      if (entryValue.Length == 0 || entryValue.Length > 256 || entryValue[entryValue.Length - 1] == ' ') return false;
      if (entryValue.Any(character => character < 0x20 || character > 0x7e || character == ',' || character == '=')) return false;
    }
    return true;
  }
